def normf(f):
    return (f or "").replace(" ","")

mismatch=[]; enriched=0; noid=[]
for i,r in enumerate(rows):
    r["cid"]=cids[i]
    r["smiles"]=smiles[i]
    r["inchikey"]=ikeys[i]
    if cids[i]:
        enriched+=1
        df=normf(r.get("formula"))
        pf=normf(mf[i])
        if df and pf and df!=pf:
            mismatch.append((r["name"], "dataset="+df, "pubchem="+pf, "cid="+str(cids[i])))
    else:
        noid.append(r["name"])

json.dump(rows, open("rows2.json","w"), ensure_ascii=False, indent=0)
print("enriched with CID:", enriched, "/ 99")
print("no PubChem id (captives):", noid)
print("FORMULA MISMATCHES (possible wrong CID):")
for m in mismatch: print("  ", m)
if not mismatch: print("   none — all resolved formulas match the dataset")
